INSERT INTO students (id,name,weight_kg,height_m,age,goal,notes,token) VALUES (1,'Mãe',62.8,1.49,NULL,'Fortalecer coxa, ganhar glúteo, definir braço (recomposição corporal)','Nível intermediário. Intensidade RIR 1–2 (terminar a série sentindo que faria só mais 1–2 repetições). Descer em 2–3 s, subir com força, segurar 1 s no topo nos exercícios de glúteo. Progressão: bateu o topo da faixa em todas as séries → +1–2 kg e volta ao início da faixa. Ciclo de 4 semanas: 3 de progressão + 1 de deload (metade das séries, mesma carga). Fazer 4x por semana (ex.: seg, ter, qui, sex).','a1b2c3d4e5f60718293a4b5c6d7e8f90a1b2c3d4e5f60718293a4b5c6d7e8f90'); -- link de teste: /aluno.php?t=a1b2c3d4e5f60718293a4b5c6d7e8f90a1b2c3d4e5f60718293a4b5c6d7e8f90
